package httpserver
import("context";"encoding/json";"errors";"net/http";"time";"github.com/wuangmmo/sodienthoai-platform/apps/api/internal/phone")
func(h ModerationHandler)Evidence(w http.ResponseWriter,r *http.Request){if !h.authorized(r){writeJSON(w,401,map[string]string{"error":"unauthorized"});return};var in phone.EvidenceInput;if json.NewDecoder(http.MaxBytesReader(w,r.Body,8192)).Decode(&in)!=nil{writeJSON(w,400,map[string]string{"error":"invalid_request"});return};ctx,cancel:=context.WithTimeout(r.Context(),3*time.Second);defer cancel();if err:=h.Service.AddClaimEvidence(ctx,r.PathValue("id"),in);err!=nil{if errors.Is(err,phone.ErrInvalidEvidence){writeJSON(w,400,map[string]string{"error":"invalid_evidence"});return};writeJSON(w,500,map[string]string{"error":"internal_error"});return};writeJSON(w,202,map[string]string{"status":"pending_review"})}
